function normalizeLocale(raw) {
  const s = String(raw ?? 'en').trim().toLowerCase();
  if (s === 'ru' || s === 'rus') return 'ru';
  return 'en';
}

function getLocale() {
  return normalizeLocale(localStorage.getItem('mnemosyne_locale'));
}

function applyLocale(locale) {
  locale = normalizeLocale(locale);
  if (!TRANSLATIONS[locale]) return;
  document.documentElement.lang = locale;
  localStorage.setItem('mnemosyne_locale', locale);
  const t = TRANSLATIONS[locale];
  const tierPrefix = t.tier_confidence_prefix || 'Confidence tier: ';
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (key && t[key] !== undefined) el.textContent = t[key];
  });
  document.querySelectorAll('[data-i18n-html]').forEach(el => {
    const key = el.getAttribute('data-i18n-html');
    if (key && t[key] !== undefined) el.innerHTML = t[key];
  });
  document.querySelectorAll('.trad-passage[data-i18n-html], .trans-passage[data-i18n-html]').forEach(el => {
    const key = el.getAttribute('data-i18n-html');
    if (key && t[key] !== undefined) el.setAttribute('lang', locale);
  });
  document.querySelectorAll('[data-i18n-aria-tier]').forEach(el => {
    const key = el.getAttribute('data-i18n-aria-tier');
    if (key && t[key] !== undefined) el.setAttribute('aria-label', tierPrefix + t[key]);
  });
  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    const key = el.getAttribute('data-i18n-title');
    if (key && t[key] !== undefined) {
      el.textContent = t[key];
      if (el.tagName === 'TITLE') document.title = t[key];
    }
  });
  document.querySelectorAll('[data-i18n-aria-label]').forEach(el => {
    const key = el.getAttribute('data-i18n-aria-label');
    if (key && t[key] !== undefined) el.setAttribute('aria-label', t[key]);
  });
  document.querySelectorAll('[data-i18n-aria-region]').forEach(el => {
    const key = el.getAttribute('data-i18n-aria-region');
    if (key && t[key] !== undefined) el.setAttribute('aria-label', t[key]);
  });
  document.querySelectorAll('.locale-b').forEach(b => {
    const isActive = (b.textContent.trim() === 'EN' && locale === 'en') ||
                     (b.textContent.trim() === 'RU' && locale === 'ru');
    b.classList.toggle('on', isActive);
    if (isActive) b.setAttribute('aria-current', 'true');
    else b.removeAttribute('aria-current');
  });
  window.dispatchEvent(new CustomEvent('mnemosyne:locale', { detail: { locale } }));
}

function initLocale() {
  const locale = normalizeLocale(localStorage.getItem('mnemosyne_locale'));
  if (locale !== 'en') applyLocale(locale);
}
